/**
 * SchemaFieldRenderer - Schema/Nested Field Renderer
 * Schema 字段渲染器 - 支持嵌套和扩展模式
 *
 * 支持 fieldType: 'schema'
 * 渲染嵌套的 ConfigSchema 字段
 *
 * 两种模式:
 * - 嵌套模式 (nestedFields): 字段在嵌套对象内渲染
 * - 扩展模式 (extendFields): 字段提升到父级 (后端已合并，前端渲染时跳过)
 */
import { html } from '../../../lib/lit/index.js';
import { FieldRenderer } from './field-renderer.js';

// 导入 FieldRegistry 以支持递归渲染
// 注意：FieldRegistry 是在 index.js 中注册的单例
let _FieldRegistry = null;

/**
 * 设置 FieldRegistry 实例（由 index.js 调用）
 */
export function setFieldRegistry(registry) {
  _FieldRegistry = registry;
}

export class SchemaFieldRenderer extends FieldRenderer {
  /**
   * 字段类型标识
   */
  static get fieldType() {
    return 'schema';
  }

  /**
   * 渲染 Schema 字段
   * @param {Object} field - 字段 Schema
   * @param {any} value - 当前值（对象）
   * @param {string|Object} error - 错误信息（字符串或嵌套错误对象）
   * @returns {TemplateResult} Lit html 模板
   */
  render(field, value, error) {
    const fieldKey = this.getFieldKey(field);

    // 扩展模式：字段在后端已合并到父级，前端无需渲染 wrapper
    // extendFields 字段会在父级通过 FieldRegistry 直接渲染
    if (field.extendFields && Array.isArray(field.extendFields)) {
      return html``;
    }

    // 嵌套模式：渲染嵌套字段
    const nestedFields = field.nestedFields || [];
    const nestedValue = value || {};

    // 判断 error 是嵌套对象还是纯字符串
    // 嵌套对象：后端返回的 SchemaConfigItem 子字段错误 Map
    // 纯字符串：SchemaConfigItem 自身的 required 验证错误
    const isNestedError = error && typeof error === 'object' && !Array.isArray(error);

    return html`
      <div class="form-group nested-group" data-field-key="${fieldKey}">
        <fieldset class="nested-fieldset">
          <legend>${this.escapeHtml(field.displayName || fieldKey)}${field.required ? html`<span class="required">*</span>` : ''}</legend>
          <div class="nested-fields">
            ${nestedFields.map(nestedField => {
              const fieldValue = nestedValue[nestedField.key] ?? nestedField.defaultValue ?? '';
              // 递归分发嵌套错误：从 error 对象中提取对应子字段的错误
              const nestedError = isNestedError ? (error[nestedField.key] || null) : null;
              // 使用父级 key 作为前缀，避免多个 SchemaConfigItem 嵌套同名字段冲突
              // 例如 mapping_1 的 port 字段 HTML name 为 "mapping_1.port"
              const prefixedField = Object.assign({}, nestedField, { key: fieldKey + '.' + nestedField.key });
              return _FieldRegistry
                ? _FieldRegistry.render(prefixedField, fieldValue, nestedError)
                : html`<div class="field-error">FieldRegistry not initialized</div>`;
            })}
          </div>
        </fieldset>
        ${!isNestedError ? this.renderError(error, html) : html``}
      </div>
    `;
  }

  /**
   * 从表单数据获取字段值
   * @param {FormData} formData - 表单数据
   * @param {Object} field - 字段 Schema
   * @returns {Object|null} 嵌套对象值
   */
  getValue(formData, field) {
    // 扩展模式：字段已合并到父级，返回 null
    if (field.extendFields && Array.isArray(field.extendFields)) {
      return null;
    }

    // 嵌套模式：收集嵌套字段值
    const nestedFields = field.nestedFields || [];
    const parentKey = this.getFieldKey(field);
    const result = {};

    for (const nestedField of nestedFields) {
      // 使用 FieldRegistry 获取嵌套字段值（带父级前缀避免同名冲突）
      const value = this.getNestedFieldValue(formData, nestedField, parentKey);
      if (value !== undefined && value !== null && value !== '') {
        result[nestedField.key] = value;
      }
    }

    return Object.keys(result).length > 0 ? result : null;
  }

  /**
   * 获取嵌套字段值
   * @param {FormData} formData - 表单数据
   * @param {Object} nestedField - 嵌套字段
   * @param {string} parentKey - 父级字段 key（用于前缀避免同名冲突）
   * @returns {any} 字段值
   */
  getNestedFieldValue(formData, nestedField, parentKey) {
    // 使用父级前缀构建唯一 key（如 "mapping_1.port"）
    const prefixedKey = parentKey + '.' + (nestedField.key || nestedField.name);

    // 如果 FieldRegistry 可用，使用带前缀的字段对象获取值
    if (_FieldRegistry) {
      const prefixedField = Object.assign({}, nestedField, { key: prefixedKey });
      return _FieldRegistry.getValue(formData, prefixedField);
    }

    // 降级处理：根据字段类型获取值
    switch (nestedField.fieldType) {
      case 'array':
        const values = formData.getAll(prefixedKey);
        return values.filter(v => v !== '');

      case 'boolean':
        const checkbox = formData.get(prefixedKey);
        return checkbox === 'true' || checkbox === 'on';

      case 'short':
      case 'numeric':
      case 'float':
        const numValue = formData.get(prefixedKey);
        return numValue ? Number(numValue) : nestedField.defaultValue;

      default:
        return formData.get(prefixedKey);
    }
  }

  /**
   * 获取默认值
   * @param {Object} field - 字段 Schema
   * @returns {Object} 默认值对象
   */
  getDefaultValue(field) {
    // 扩展模式返回空对象
    if (field.extendFields) {
      return {};
    }

    // 嵌套模式：收集嵌套字段默认值
    const nestedFields = field.nestedFields || [];
    const result = {};

    for (const nestedField of nestedFields) {
      if (nestedField.defaultValue !== undefined && nestedField.defaultValue !== null) {
        result[nestedField.key] = nestedField.defaultValue;
      }
    }

    return result;
  }
}
