/**
 * 页面内确认/提示对话框（替代 window.confirm / window.alert）。
 *
 * Electron 下 Chromium 原生 confirm/alert 关闭后常出现焦点丢失，
 * 导致输入框、下拉等无法交互；浏览器一般无此问题。使用 DOM 弹窗可彻底规避。
 */

const HOST_ID = 'ecat-app-dialog-host';
const STYLE_ID = 'ecat-app-dialog-styles';

function ensureStyles() {
  if (document.getElementById(STYLE_ID)) return;
  const style = document.createElement('style');
  style.id = STYLE_ID;
  style.textContent = `
    #${HOST_ID} {
      position: fixed; inset: 0; z-index: 2147483000;
      display: none; align-items: center; justify-content: center;
      background: rgba(15, 23, 42, 0.45);
      font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
    }
    #${HOST_ID}.open { display: flex; }
    #${HOST_ID} .ecat-dlg {
      background: #fff; border-radius: 12px; width: min(440px, 92vw);
      box-shadow: 0 20px 50px rgba(0,0,0,.25); overflow: hidden;
    }
    #${HOST_ID} .ecat-dlg-title {
      padding: 16px 20px 0; font-size: 16px; font-weight: 600; color: #111827;
    }
    #${HOST_ID} .ecat-dlg-body {
      padding: 12px 20px 8px; font-size: 14px; line-height: 1.55; color: #374151;
      white-space: pre-wrap; word-break: break-word; max-height: 60vh; overflow: auto;
    }
    #${HOST_ID} .ecat-dlg-actions {
      display: flex; justify-content: flex-end; gap: 8px; padding: 12px 16px 16px;
    }
    #${HOST_ID} .ecat-dlg-btn {
      min-width: 72px; padding: 8px 16px; border-radius: 6px; border: 1px solid #d1d5db;
      background: #fff; color: #374151; font-size: 14px; cursor: pointer;
    }
    #${HOST_ID} .ecat-dlg-btn:hover { background: #f9fafb; }
    #${HOST_ID} .ecat-dlg-btn.primary {
      background: #2563eb; border-color: #2563eb; color: #fff;
    }
    #${HOST_ID} .ecat-dlg-btn.primary:hover { background: #1d4ed8; }
    #${HOST_ID} .ecat-dlg-btn:focus { outline: 2px solid #93c5fd; outline-offset: 1px; }
  `;
  document.head.appendChild(style);
}

function ensureHost() {
  ensureStyles();
  let host = document.getElementById(HOST_ID);
  if (!host) {
    host = document.createElement('div');
    host.id = HOST_ID;
    host.setAttribute('role', 'presentation');
    document.body.appendChild(host);
  }
  return host;
}

function showDialog({ title, message, showCancel }) {
  return new Promise((resolve) => {
    const host = ensureHost();
    const previouslyFocused = document.activeElement;

    host.innerHTML = `
      <div class="ecat-dlg" role="alertdialog" aria-modal="true" aria-labelledby="ecat-dlg-title">
        <div class="ecat-dlg-title" id="ecat-dlg-title"></div>
        <div class="ecat-dlg-body"></div>
        <div class="ecat-dlg-actions"></div>
      </div>
    `;
    host.querySelector('.ecat-dlg-title').textContent = title;
    host.querySelector('.ecat-dlg-body').textContent = message;

    const actions = host.querySelector('.ecat-dlg-actions');
    const okBtn = document.createElement('button');
    okBtn.type = 'button';
    okBtn.className = 'ecat-dlg-btn primary';
    okBtn.textContent = '确定';

    let cancelBtn = null;
    if (showCancel) {
      cancelBtn = document.createElement('button');
      cancelBtn.type = 'button';
      cancelBtn.className = 'ecat-dlg-btn';
      cancelBtn.textContent = '取消';
      actions.appendChild(cancelBtn);
    }
    actions.appendChild(okBtn);

    const finish = (value) => {
      host.classList.remove('open');
      host.innerHTML = '';
      document.removeEventListener('keydown', onKey);
      if (previouslyFocused && typeof previouslyFocused.focus === 'function') {
        try { previouslyFocused.focus(); } catch (_) { /* ignore */ }
      }
      resolve(value);
    };

    const onKey = (e) => {
      if (e.key === 'Escape' && showCancel) {
        e.preventDefault();
        finish(false);
      } else if (e.key === 'Enter') {
        e.preventDefault();
        finish(true);
      }
    };

    okBtn.addEventListener('click', () => finish(true));
    if (cancelBtn) cancelBtn.addEventListener('click', () => finish(false));
    host.addEventListener('click', (e) => {
      if (e.target === host && showCancel) finish(false);
    });
    document.addEventListener('keydown', onKey);

    host.classList.add('open');
    okBtn.focus();
  });
}

/** @returns {Promise<boolean>} */
export function appConfirm(message, title = '确认') {
  return showDialog({ title, message: String(message ?? ''), showCancel: true });
}

/** @returns {Promise<void>} */
export async function appAlert(message, title = '提示') {
  await showDialog({ title, message: String(message ?? ''), showCancel: false });
}
