/**
 * ShortFieldRenderer - Short Field Renderer
 * 短整数字段渲染器
 *
 * 支持 fieldType: 'short'
 * 渲染为 <input type="number" step="1">
 * 用于存储短整型数值（-32768 到 32767）
 */
import { html } from '../../../lib/lit/index.js';
import { FieldRenderer } from './field-renderer.js';

// Short 类型范围
const SHORT_MIN = -32768;
const SHORT_MAX = 32767;

export class ShortFieldRenderer extends FieldRenderer {
  /**
   * 字段类型标识
   */
  static get fieldType() {
    return 'short';
  }

  /**
   * 渲染短整数字段
   * @param {Object} field - 字段 Schema
   * @param {any} value - 当前值
   * @param {string} error - 错误信息
   * @returns {TemplateResult} Lit html 模板
   */
  render(field, value, error) {
    const fieldKey = this.getFieldKey(field);
    const displayValue = value ?? field.defaultValue ?? '';
    // 注意：后端无 range 时 min/max 序列化为 null（非 undefined），必须用 != null 同时覆盖两者；
    // 否则 Math.max(null, SHORT_MIN) 会把 null 强转为 0，导致 min=max=0（只允许 0，见 BUG-精确度）。
    const min = field.min != null ? Math.max(field.min, SHORT_MIN) : SHORT_MIN;
    const max = field.max != null ? Math.min(field.max, SHORT_MAX) : SHORT_MAX;

    return html`
      <div class="form-group">
        ${this.renderLabel(field, html)}
        <input
          type="number"
          id="${fieldKey}"
          name="${fieldKey}"
          .value=${displayValue}
          min="${min}"
          max="${max}"
          step="1"
          placeholder="${field.placeholder || '0'}"
          ?required=${field.required}
          ?readonly=${field.readOnly || field.readonly}
        />
        ${field.description && !error ? html`<div class="hint">${this.escapeHtml(field.description)}</div>` : ''}
        ${this.renderError(error, html)}
      </div>
    `;
  }

  /**
   * 从表单数据获取字段值
   * 将字符串转换为短整型
   * @param {FormData} formData - 表单数据
   * @param {Object} field - 字段 Schema
   * @returns {number|null} 短整型值或 null
   */
  getValue(formData, field) {
    const fieldKey = this.getFieldKey(field);
    const rawValue = formData.get(fieldKey);

    if (rawValue === null || rawValue === '') {
      return field.defaultValue !== undefined ? this.toShort(field.defaultValue) : null;
    }

    const numValue = parseInt(rawValue, 10);
    if (isNaN(numValue)) {
      return null;
    }

    // 限制在 Short 范围内
    return Math.max(SHORT_MIN, Math.min(SHORT_MAX, numValue));
  }

  /**
   * 获取默认值
   * @param {Object} field - 字段 Schema
   * @returns {number|null} 短整型值或 null
   */
  getDefaultValue(field) {
    const defaultVal = field.defaultValue;
    if (defaultVal === null || defaultVal === undefined) {
      return null;
    }
    return this.toShort(defaultVal);
  }

  /**
   * 转换为短整型
   * @param {any} value - 原始值
   * @returns {number|null} 短整型值
   */
  toShort(value) {
    const numValue = parseInt(value, 10);
    if (isNaN(numValue)) {
      return null;
    }
    return Math.max(SHORT_MIN, Math.min(SHORT_MAX, numValue));
  }
}
