/**
 * YamlFieldRenderer - YAML 字段渲染器
 *
 * 支持 fieldType: 'yaml'。按 field.readOnly 分两种形态(YamlConfigItem 构造函数默认 readOnly=true):
 *   - 只读(readOnly=true):渲染只读 <textarea>(可全文选中复制,点击全选)展示。用于"配置预览/导出"等
 *     需用户复制的场景(config_summary 配置详情、export_yaml 导出映射、verify_results 实采结果)。
 *     getValue 返 field.defaultValue(展示值),与其他 renderer 的 round-trip 契约一致——只读字段值照常回传。
 *     这让"仅含只读 yaml 字段"的步(如 step_verify 的 verify_results)能靠非空 userInput 推进,
 *     不会因 FormData 空 {} 被后端 isEmpty() 误判为"首次展示"而卡步。
 *   - 可编辑(readOnly=false):渲染 <textarea>,getValue 读 formData 文本。供"导入 YML"等需用户粘贴的场景
 *     (如 register_mappings_yaml,须在 schema 显式 .readOnly(false))。
 */
import { html } from '../../../lib/lit/index.js';
import { FieldRenderer } from './field-renderer.js';

const STYLE = html`<style>
  .yaml-label { margin-bottom: 6px; font-weight: 500; }
  .yaml-content {
    min-height: 80px; max-height: 300px; overflow-y: auto;
    padding: 12px; margin: 0;
    font-size: 13px; line-height: 1.5;
    background: #f8f9fa; border: 1px solid #e9ecef; border-radius: 4px;
    white-space: pre-wrap; word-break: break-all;
  }
  .yaml-textarea {
    width: 100%; min-height: 240px; padding: 12px; box-sizing: border-box;
    font-size: 13px; line-height: 1.5;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    border: 1px solid var(--border, #ced4da); border-radius: var(--radius-sm, 4px);
    resize: vertical;
  }
  .yaml-textarea:focus { outline: none; border-color: var(--primary, #2563eb); }
  .yaml-readonly { background: #f8f9fa; color: var(--text, #1f2937); cursor: text; }
</style>`;

export class YamlFieldRenderer extends FieldRenderer {
  static get fieldType() {
    return 'yaml';
  }

  /** YamlConfigItem 构造函数默认 readOnly=true;导入等场景显式 .readOnly(false) 改写。 */
  _isReadOnly(field) {
    return !!(field.readOnly || field.readonly);
  }

  /**
   * 按 readOnly 渲染:只读 <pre> / 可编辑 <textarea>。
   * @returns {TemplateResult} Lit html 模板
   */
  render(field, value, error) {
    const content = value ?? field.defaultValue ?? '';
    const label = field.displayName
      ? html`<label class="yaml-label">${this.escapeHtml(field.displayName)}</label>`
      : '';
    const hint = field.description ? html`<div class="hint">${this.escapeHtml(field.description)}</div>` : '';

    if (this._isReadOnly(field)) {
      return html`
        ${STYLE}
        <div class="form-group yaml-display">
          ${label} ${hint}
          <textarea class="yaml-textarea yaml-readonly" readonly .value=${content}
                    @click=${e => e.target.select()}
                    title="点击全选,Ctrl+C 复制"></textarea>
        </div>
      `;
    }
    const fieldKey = this.getFieldKey(field);
    return html`
      ${STYLE}
      <div class="form-group yaml-edit">
        ${label} ${hint}
        <textarea id="${fieldKey}" name="${fieldKey}" class="yaml-textarea"
                  placeholder="${field.placeholder || ''}" .value=${content}></textarea>
        ${this.renderError(error, html)}
      </div>
    `;
  }

  /**
   * 只读:回传展示值(field.defaultValue),对齐其他 renderer 的 round-trip 契约。
   * 可编辑:回传 textarea 文本。
   */
  getValue(formData, field) {
    const fieldKey = this.getFieldKey(field);
    if (this._isReadOnly(field)) {
      const dv = field.defaultValue;
      return dv == null ? '' : dv;
    }
    const raw = formData.get(fieldKey);
    return raw != null ? raw : (field.defaultValue ?? '');
  }

  getDefaultValue(field) {
    return field.defaultValue;
  }
}
