/**
 * ArrayFieldRenderer - Array/Multi-Select Field Renderer
 * 数组/多选字段渲染器
 *
 * 支持 fieldType: 'array'
 * 渲染为多选框组（checkbox group）
 * 用户从预定义选项中选择多个值
 */
import { html } from '../../../lib/lit/index.js';
import { FieldRenderer } from './field-renderer.js';

export class ArrayFieldRenderer extends FieldRenderer {
  /**
   * 字段类型标识
   */
  static get fieldType() {
    return 'array';
  }

  /**
   * 渲染多选字段（checkbox 组）
   * @param {Object} field - 字段 Schema
   * @param {any} value - 当前值（数组）
   * @param {string} error - 错误信息
   * @returns {TemplateResult} Lit html 模板
   */
  render(field, value, error) {
    const fieldKey = this.getFieldKey(field);
    const options = this.parseOptions(field.options || []);
    const selectedValues = this.normalizeValue(value ?? field.defaultValue ?? []);

    return html`
      <div class="form-group">
        ${this.renderLabel(field, html)}
        <div class="checkbox-group" id="${fieldKey}" role="group" aria-labelledby="${fieldKey}-label">
          ${options.map(opt => {
            const optValue = typeof opt === 'object' ? opt.value : opt;
            const optLabel = typeof opt === 'object' ? (opt.label || opt.value) : opt;
            const isChecked = selectedValues.includes(optValue);
            return html`
              <div class="checkbox-wrapper">
                <input
                  type="checkbox"
                  name="${fieldKey}"
                  value="${optValue}"
                  id="${fieldKey}_${optValue}"
                  ?checked=${isChecked}
                  ?disabled=${field.readonly}
                />
                <label for="${fieldKey}_${optValue}">${this.escapeHtml(optLabel)}</label>
              </div>
            `;
          })}
        </div>
        ${field.description && !error ? html`<div class="hint">${this.escapeHtml(field.description)}</div>` : ''}
        ${this.renderError(error, html)}
      </div>
    `;
  }

  /**
   * 从表单数据获取字段值
   * @param {FormData} formData - 表单数据
   * @param {Object} field - 字段 Schema
   * @returns {string[]} 选中的值数组
   */
  getValue(formData, field) {
    const fieldKey = this.getFieldKey(field);
    // FormData.getAll() 返回所有选中 checkbox 的值
    const values = formData.getAll(fieldKey);
    return values.filter(v => v !== ''); // 过滤空值
  }

  /**
   * 获取默认值
   * @param {Object} field - 字段 Schema
   * @returns {string[]} 默认值数组
   */
  getDefaultValue(field) {
    return this.normalizeValue(field.defaultValue || []);
  }

  /**
   * 解析选项数组
   * 支持多种格式：
   * - 字符串数组: ['option1', 'option2']
   * - 对象数组: [{value: 'v1', label: 'Label 1'}]
   * @param {Array} options - 原始选项数组
   * @returns {Array} 标准化的选项数组
   */
  parseOptions(options) {
    if (!Array.isArray(options)) {
      console.warn('[ArrayFieldRenderer] options is not an array:', options);
      return [];
    }
    return options;
  }

  /**
   * 标准化值为数组
   * @param {any} value - 任意值
   * @returns {string[]} 字符串数组
   */
  normalizeValue(value) {
    if (Array.isArray(value)) {
      return value.map(v => String(v));
    }
    if (value === null || value === undefined) {
      return [];
    }
    // 尝试解析 JSON 字符串
    if (typeof value === 'string') {
      try {
        const parsed = JSON.parse(value);
        if (Array.isArray(parsed)) {
          return parsed.map(v => String(v));
        }
      } catch {
        // 不是 JSON，按逗号分割
        return value.split(',').map(v => v.trim()).filter(v => v);
      }
    }
    return [String(value)];
  }
}
