/**
 * EnumFieldRenderer - Enum/Select Field Renderer
 * 枚举/下拉字段渲染器
 *
 * 支持 fieldType: 'enum', 'select'
 * 渲染为 <select>
 */
import { html } from '../../../lib/lit/index.js';
import { FieldRenderer } from './field-renderer.js';

export class EnumFieldRenderer extends FieldRenderer {
  /**
   * 字段类型标识
   */
  static get fieldType() {
    return 'enum';
  }

  /**
   * 渲染枚举字段（下拉选择框）
   * @param {Object} field - 字段 Schema
   * @param {any} value - 当前值
   * @param {string} error - 错误信息
   * @returns {TemplateResult} Lit html 模板
   */
  render(field, value, error) {
    const fieldKey = this.getFieldKey(field);
    const options = this.parseOptions(field.options || []);
    const displayMapping = field.displayMapping || {};
    const currentValue = value ?? field.defaultValue ?? '';

    // 始终显示"请选择"占位选项
    // 原因：1. 表示用户未选择的状态 2. 选填字段需要能够"取消选择"
    // 如果有当前值，则对应选项会被选中；否则占位选项被选中
    const hasCurrentValue = currentValue !== '' && currentValue != null;

    return html`
      <div class="form-group">
        ${this.renderLabel(field, html)}
        <select
          id="${fieldKey}"
          name="${fieldKey}"
        >
          <option value="" ?selected=${!hasCurrentValue}>${field.placeholder || '请选择...'}</option>
          ${options.map(opt => {
            const optValue = typeof opt === 'object' ? opt.value : opt;
            const optLabel = typeof opt === 'object'
              ? (opt.label || opt.value)
              : (displayMapping[opt] || opt);
            return html`
              <option
                value="${optValue}"
                ?selected=${String(currentValue) === String(optValue)}
              >
                ${this.escapeHtml(optLabel)}
              </option>
            `;
          })}
        </select>
        ${field.description && !error ? html`<div class="hint">${this.escapeHtml(field.description)}</div>` : ''}
        ${this.renderError(error, html)}
      </div>
    `;
  }

  /**
   * 从表单数据获取字段值
   * @param {FormData} formData - 表单数据
   * @param {Object} field - 字段 Schema
   * @returns {string} 选择的值
   */
  getValue(formData, field) {
    const fieldKey = this.getFieldKey(field);
    const rawValue = formData.get(fieldKey);

    // 直接返回用户选择的值（包括空值）
    // - 空值表示用户选择了"请选择..."，表示未选择
    // - 必填字段会由验证器处理空值情况
    return rawValue || '';
  }

  /**
   * 获取默认值
   */
  getDefaultValue(field) {
    return field.defaultValue ?? '';
  }

  /**
   * 解析选项数组
   * 支持多种格式：
   * - 字符串数组: ['option1', 'option2']
   * - 对象数组: [{value: 'v1', label: 'Label 1'}]
   * @param {Array} options - 原始选项数组
   * @returns {Array} 标准化的选项数组
   */
  parseOptions(options) {
    if (!Array.isArray(options)) {
      console.warn('[EnumFieldRenderer] options is not an array:', options);
      return [];
    }
    return options;
  }
}
