/**
 * TextFieldRenderer - Text Field Renderer
 * 文本字段渲染器
 *
 * 支持 fieldType: 'text'
 * 渲染为 <input type="text">
 */
import { html, ifDefined } from '../../../lib/lit/index.js';
import { FieldRenderer } from './field-renderer.js';

export class TextFieldRenderer extends FieldRenderer {
  /**
   * 字段类型标识
   */
  static get fieldType() {
    return 'text';
  }

  /**
   * 渲染文本字段
   * @param {Object} field - 字段 Schema
   * @param {any} value - 当前值
   * @param {string} error - 错误信息
   * @returns {TemplateResult} Lit html 模板
   */
  render(field, value, error) {
    const fieldKey = this.getFieldKey(field);
    const displayValue = value ?? field.defaultValue ?? '';

    return html`
      <div class="form-group">
        ${this.renderLabel(field, html)}
        <input
          type="text"
          id="${fieldKey}"
          name="${fieldKey}"
          .value=${displayValue}
          placeholder="${field.placeholder || ''}"
          minlength="${ifDefined(field.minLength)}"
          maxlength="${ifDefined(field.maxLength)}"
          pattern="${ifDefined(field.pattern)}"
          ?required=${field.required}
          ?readonly=${field.readOnly || field.readonly}
        />
        ${field.description && !error ? html`<div class="hint">${this.escapeHtml(field.description)}</div>` : ''}
        ${this.renderError(error, html)}
      </div>
    `;
  }

  /**
   * 获取默认值
   */
  getDefaultValue(field) {
    return field.defaultValue ?? '';
  }
}
